require "rails_helper"
require "rake"

RSpec.describe "timekeeping:alerts" do
  it "exits non-zero without printing no alerts or the token when the metrics endpoint refuses the token" do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.ensure_initial!
    token = SecureRandom.hex(16)
    saved = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .to_return(status: 401, body: JSON.generate(reason: "unauthorized"))
    log = StringIO.new
    allow(Rails.logger).to receive(:warn) { |message| log.puts(message) }
    allow(Rails.logger).to receive(:error) { |message| log.puts(message) }

    stdout = StringIO.new
    stderr = StringIO.new
    original_stdout, original_stderr = $stdout, $stderr
    $stdout, $stderr = stdout, stderr
    begin
      expect { Rake::Task["timekeeping:alerts"].invoke }.to raise_error(SystemExit) { |exit| expect(exit.success?).to be(false) }
    ensure
      $stdout, $stderr = original_stdout, original_stderr
    end

    printed = stdout.string + stderr.string + log.string
    # A refused or unreachable endpoint must not look like a healthy one with nothing to report.
    expect(printed).not_to match(/no alerts/i)
    expect(printed).not_to include(token)
  ensure
    %w[TIMEKEEPING_SERVICE_TOKEN TIMEKEEPING_BASE_URL].each { |key| ENV[key] = saved[key] }
  end
end

