RSpec.describe "timekeeping:alerts output" do
  let(:alerts_task_token) { SecureRandom.hex(16) }

  around do |example|
    saved = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = alerts_task_token
    example.run
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = saved[key] }
  end

  before do
    Rails.application.load_tasks if Rake::Task.tasks.empty?
    Rake::Task["timekeeping:alerts"].reenable
    TimekeepingOwnership.ensure_initial!
  end

  def alerts_task_metrics_body(windows_by_company)
    {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => windows_by_company.map { |company_id, windows| { "company_id" => company_id, "windows" => windows } }
    }
  end

  def stub_alerts_task_metrics(body)
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{alerts_task_token}" })
      .to_return(status: 200, body: JSON.generate(body))
  end

  it "logs a stale_generation alert with the company that answered it" do
    current_window = Time.at((Time.current.to_i / 300) * 300).utc.iso8601
    stub_alerts_task_metrics(alerts_task_metrics_body(
      9 => [{ "window_start" => current_window, "writes" => 5, "reference_unavailable" => 0, "stale_generation" => 1,
              "latency_ms_sum" => 50, "latency_ms_buckets" => { "25" => 5 } }]
    ))
    allow(Rails.logger).to receive(:warn)

    expect { Rake::Task["timekeeping:alerts"].invoke }
      .to output(/alert=stale_generation company_id=9 value=1 threshold=1/).to_stdout
    expect(Rails.logger).to have_received(:warn).with(/alert=stale_generation company_id=9/)
  end

  it "prints no alerts and the signals that have no source when nothing crosses a threshold" do
    stub_alerts_task_metrics(alerts_task_metrics_body({}))

    expect { Rake::Task["timekeeping:alerts"].invoke }
      .to output(/no alerts\n.*signals not sourced: write_pause_seconds, prepare_refusals_by_company/m).to_stdout
  end

  it "exits non-zero with an error and no 'no alerts' line when the endpoint is unreachable" do
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics").to_raise(Errno::ECONNREFUSED)

    expect { Rake::Task["timekeeping:alerts"].invoke }
      .to raise_error(SystemExit) { |exit| expect(exit.status).not_to eq(0) }
      .and output(/metrics endpoint unreachable/).to_stderr
      .and output(satisfy { |stdout| !stdout.include?("no alerts") }).to_stdout
  end
end
